import {BUILDINGS as DESIGN} from './design-data.js';
import * as G from './horizons.js';import {icon} from './ui-icons.js';
const esc=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=n=>Math.floor(n).toLocaleString('es-CO'),duration=n=>Math.ceil(n/60)+' min';
export const art=(type,unit=false,tier=0,level=1)=>`<canvas data-art="${type}" data-level="${level}" data-tier="${tier}" ${unit?'data-unit="true"':''}></canvas>`;
export const CATEGORIES={village:{name:'Pueblo',icon:'home',types:['camp','house','well','cistern','school','hospital','embassy','market']},upgrades:{name:'Mejoras',icon:'build',types:[]},production:{name:'Recursos',icon:'leaf',types:['farm','mine','depot','waterworks','greenhouse']},military:{name:'Defensa',icon:'army',types:['barracks','tower','dock']},industry:{name:'Tecnología',icon:'science',types:['refinery','garage','reactor','airfield','lab','fusion','starforge']},roads:{name:'Caminos',icon:'road',types:[]}};
CATEGORIES.logistics={name:'Logística',icon:'road',types:[]};for(const[id,spec]of Object.entries(G.STRUCTURES)){if(!spec.expansion)continue;const group={village:'village',production:'production',naval:'logistics',logistics:'logistics',science:'industry',energy:'industry',military:'military'}[spec.category];CATEGORIES[group].types.push(id);}
export function buildCatalog(s,category='village',locked=false,query=''){const m=G.currentMap(s),c=CATEGORIES[category],matches=id=>!query||[G.STRUCTURES[id].name,G.STRUCTURES[id].description,DESIGN[id].outputs].join(' ').toLocaleLowerCase('es').includes(query.toLocaleLowerCase('es'));if(category==='roads')return `<div class="network-tools"><div><span class="eyebrow">DISEÑA LA RED</span><h3>Tu ciudad empieza con un camino.</h3><p>Marca dos puntos para una recta o tres para una curva. El precio se muestra antes de ordenar la obra.</p></div><label>Acabado<select id="road-grade">${Object.entries(G.ROAD_GRADES).map(([k,v])=>`<option value="${k}" ${s.era<v.era?'disabled':''}>${v.name}${s.era<v.era?' · era '+(v.era+1):''}</option>`).join('')}</select></label><button data-action="road-tool" data-type="straight">${icon('road')}Recta</button><button data-action="road-tool" data-type="curve">${icon('rotate')}Curva</button><button data-tab="routes">Rutas y suministros ${icon('arrow')}</button><a class="study-link" href="./codex.html?section=engineering">Estudiar terreno, carga y alternativas ↗</a></div>`;
 if(category==='upgrades')return m.buildings.filter(b=>b.hp>0&&b.progress>=1&&matches(b.type)).map(b=>{const q=G.upgradeQuote(s,m,b,G.STRUCTURES[b.type]),job=m.civicJobs.find(j=>j.building===b.id&&j.kind==='upgrade');return `<button class="build-card" data-action="inspect-upgrade" data-id="${b.id}"><div class="build-card-art">${art(b.type,false,b.tier,b.level)}</div><strong>${G.STRUCTURES[b.type].name}</strong><small>${job?'Mejora en curso':q.maxed?'Máximo de la era':'Nivel '+b.level+' → '+(q.refit?'nuevo plano':q.next)}</small><span class="build-time">${icon(job?'clock':'build')}${job?'En construcción':q.maxed?'Completado':duration(q.duration)}</span></button>`;}).join('')||'<div class="empty">Aquí aparecerán las mejoras de tus edificios terminados.</div>';const types=c.types.filter(k=>(locked||G.STRUCTURES[k].era<=s.era)&&matches(k));return types.map(type=>{const spec=G.STRUCTURES[type],unlocked=s.era>=spec.era,owned=m.buildings.filter(b=>b.hp>0&&b.type===type).length;return `<button class="build-card ${unlocked?'':'locked'}" data-action="build-tool" data-type="${type}" title="${esc(spec.description)}"><div class="build-card-art">${art(type,false,s.era)}${owned?`<span class="owned-count">${owned}</span>`:''}</div><strong>${spec.name}</strong><span class="build-purpose">${DESIGN[type].outputs}</span><small>${unlocked?Object.entries(spec.cost).map(([k,v])=>fmt(v)+' '+G.STOCK_NAMES[k]).join(' · '):'ERA '+(spec.era+1)+' · '+G.ERAS[spec.era].name}</small><span class="build-time">${icon(unlocked?'clock':'era')}${unlocked?duration(spec.time):'Por descubrir'}</span></button>`;}).join('')||'<div class="empty">Esta categoría se abre en eras posteriores. Activa «Ver bloqueados» para consultarla.</div>';
}
export function selectionSummary(s,selected){const m=G.currentMap(s),units=m.units.filter(u=>u.hp>0&&!u.embarked&&selected.includes(u.id)),b=m.buildings.find(b=>b.hp>0&&selected.includes(b.id));if(!b&&!units.length)return'';const u=units[0],spec=b?G.STRUCTURES[b.type]:G.TROOPS[u.type],hp=b?G.buildingStats(b,spec).hp:units.reduce((n,u)=>n+u.maxHp,0),current=b?b.hp:units.reduce((n,u)=>n+u.hp,0),sub=b?(b.progress<1?'Construcción · '+Math.floor(b.progress*100)+'%':'Nivel '+b.level+' · '+G.ERAS[b.tier].name):units.length>1?Object.entries(units.reduce((p,u)=>(p[G.TROOPS[u.type].name]=(p[G.TROOPS[u.type].name]||0)+1,p),{})).map(([k,n])=>n+' '+k).join(' · '):G.SPECIES[u.species].name+' · '+({hold:'En espera',move:'En marcha',attackMove:'Avanzar y atacar',attack:'En combate',gather:'Recolectando',construct:'Construyendo',dig:'Excavando',deliver:'Entregando',explore:'Explorando',operate:'Trabajando',study:'Investigando',upgrade:'Mejorando'}[u.order.kind]||'Trabajando');return `<div class="selection-portrait">${art(b?b.type:u.type,!b,b?.tier??u.technology,b?.level||Math.max(1,u.training||1))}</div><div class="selection-heading"><strong>${b?spec.name:units.length>1?units.length+' unidades':spec.name}</strong><small>${esc(sub)}</small><div class="selection-health" title="${Math.ceil(current)} / ${Math.ceil(hp)} integridad"><i style="width:${Math.min(100,current/hp*100)}%"></i></div></div><button data-action="inspect-selection" class="icon-button" aria-label="Detalles de la selección">${icon('info')}</button><button data-action="clear-selection" class="icon-button" aria-label="Quitar selección">${icon('close')}</button>`;
}
const command=(key,label,symbol,mode)=>`<button data-action="command" data-type="${key}" class="${mode===key?'active':''}" title="${label}">${icon(symbol)}<span>${label}</span></button>`;
export function commandBar(s,selected,mode,formation){const m=G.currentMap(s),units=m.units.filter(u=>u.hp>0&&!u.embarked&&selected.includes(u.id)),b=m.buildings.find(b=>selected.includes(b.id)&&b.hp>0);if(b)return `<button class="primary" data-action="inspect-upgrade" data-id="${b.id}">${icon('build')}<span>${b.progress<1?'Detalles':'Mejorar'}</span></button>${b.progress<1?`<button data-action="resume-build" data-id="${b.id}">${icon('workers')}Continuar obra</button>`:''}${Object.values(G.TROOPS).some(u=>u.facility===b.type)?`<button data-action="rally-mode">${icon('flag')}Reunión</button><button data-tab="army">${icon('army')}Reclutar</button>`:''}`;
 if(!units.length)return'';const training=units.length===1?'<button data-action="train-selected" title="Mejorar equipo en su instalación">'+icon('build')+'<span>Equipo '+Math.min(10,(units[0].training||0)+1)+'</span></button>':'';const civilian=units.every(u=>G.TROOPS[u.type].civilian),naval=units.some(u=>G.TROOPS[u.type].naval),military=units.some(u=>!G.TROOPS[u.type].civilian);return command('move','Mover','arrow',mode)+command(civilian?'gather':'attackMove',civilian?'Recolectar':'Atacar',''+(civilian?'gather':'target'),mode)+command('hold','Detener','stop',mode)+`<details class="command-more"><summary>${icon('more')}<span>Órdenes</span></summary><div class="command-popover">${training}${command('explore','Explorar','explore',mode)}${civilian?`<button data-action="return-cargo">${icon('home')}Entregar carga</button><div class="popover-divider"></div>${['wood','stone','food','water'].map(k=>`<button data-action="quick-gather" data-type="${k}">${icon('workers')}${G.STOCK_NAMES[k]}</button>`).join('')}`:''}${military?`<div class="popover-divider"></div><label>Formación<select id="formation-select">${Object.entries(G.FORMATIONS).map(([k,v])=>`<option value="${k}" ${formation===k?'selected':''}>${v}</option>`).join('')}</select></label><label>Comportamiento<select id="stance-select">${Object.entries(G.STANCES).map(([k,v])=>`<option value="${k}" ${(units[0].stance||'defend')===k?'selected':''}>${v}</option>`).join('')}</select></label>`:''}${command('embark','Embarcar','ship',mode)}${naval?command('unload','Desembarcar','ship',mode)+'<button data-action="supply-load">Cargar provisiones</button><button data-action="supply-unload">Entregar provisiones</button>':''}<button data-action="box-mode">${icon('grid')}Seleccionar área</button><button data-action="all">${icon('grid')}Seleccionar todas</button></div></details>`;
}
export function placementPanel(s,type,point,rotation){const spec=G.STRUCTURES[type],q=point?G.constructionQuote(s,type,point.x,point.y):null;return `<div class="placement-title">${icon('build')}<div><strong>${spec.name}</strong><small>${point?(q.ok?'Ubicación válida':q.message):'Toca el suelo para situar el edificio. Puedes arrastrarlo.'}</small></div></div><div class="placement-price">${Object.entries(spec.cost).map(([k,v])=>`<span class="${G.currentMap(s).stock[k]<v?'missing':''}">${fmt(v)} ${G.STOCK_NAMES[k]}</span>`).join('')}<span>${duration(spec.time)}</span></div><div class="placement-actions">${G.DEFENSES[type]&&point?'<button data-action="study-defense">Estudiar defensa</button>':''}${s.species.length>1?'<label>Pueblo <select id="build-species">'+s.species.map(id=>'<option value="'+id+'">'+G.SPECIES[id].name+'</option>').join('')+'</select></label>':''}<button data-action="rotate-building" title="Girar · R">${icon('rotate')}<span>${rotation*90}°</span></button><button data-action="cancel-tool">${icon('close')}Cancelar</button><button class="primary" data-action="confirm-building" ${!q?.ok?'disabled':''}>${icon('check')}Construir</button></div>`;}
